pm.test('200', () => pm.response.to.have.status(200));
const j = pm.response.json();
pm.test('ok true', () => pm.expect(j.ok).to.be.true);
pm.test('minimal satu region', () => pm.expect(j.regions).to.be.an('array').that.is.not.empty);
j.regions.forEach((r) => {
  pm.test(r.name + ': node/edge/ban masuk akal', () => {
    pm.expect(r.nodes).to.be.above(0);
    pm.expect(r.edges).to.be.above(0);
    pm.expect(r.bans).to.be.at.least(0);
    pm.expect(r.only_rules).to.be.at.least(0);
    pm.expect(r.format).to.be.at.least(3);
  });
});
pm.test('provenance lengkap (format 4)', () => {
  const r = j.regions[0];
  pm.expect(r.pbf_sha256).to.match(/^[0-9a-f]{64}$/);
  pm.expect(r.profile_sha256).to.match(/^[0-9a-f]{64}$/);
  pm.expect(r.built_at).to.be.a('string').and.not.empty;
  pm.expect(r.extractor).to.be.a('string').and.not.empty;
});
console.log(j.version, '-', j.regions.map((r) => r.name + ':' + r.nodes).join(', '));

