const code = pm.response.code;
pm.test('200 dengan -max-route-km 0, atau 422 bila cap default / graf tidak lengkap', () => pm.expect([200, 422]).to.include(code));
if (code === 200) {
  const j = pm.response.json();
  pm.test('region gabungan', () => pm.expect(j.region).to.equal('java+sumatra'));
  pm.test('tiga leg road/ferry/road', () => {
    pm.expect(j.legs).to.be.an('array').with.lengthOf(3);
    pm.expect(j.legs.map((l) => l.mode)).to.eql(['road', 'ferry', 'road']);
  });
  pm.test('ferry dan jarak', () => {
    pm.expect(j.ferry_m).to.be.above(0);
    pm.expect(j.ferry_spans).to.be.an('array').that.is.not.empty;
    const sum = j.legs.reduce((m, l) => m + l.distance_m, 0);
    pm.expect(sum).to.equal(j.distance_m);
  });
  console.log(j.region, j.distance_m + 'm', j.legs.length + ' leg');
} else {
  pm.test('pesan error jelas', () => pm.expect(pm.response.json().error).to.be.a('string').and.not.empty);
  console.log('422:', pm.response.json().error, '- jalankan server dengan -max-route-km 0');
}
